subscription WorkflowOutputMatch {
  workflow_output(where: { org_id: { eq: $org_id } }, order_by: { created_at: desc }, limit: 1) {
    id
    org_id
    workflow_run_id
    kind
    scope
    topic
    mood
    title
    created_at
  }
}

subscription WorkflowOutputMatch {
  workflow_output(where: { org_id: { eq: $org_id }, scope: { eq: $scope }, topic: { eq: $topic }, mood: { eq: $mood }, kind: { in: ["alert", "note"] } }, order_by: { created_at: desc }, limit: 1) {
    id
    org_id
    workflow_run_id
    kind
    scope
    topic
    mood
    title
    created_at
  }
}

subscription WorkflowOutputMatch {
  workflow_output(where: { org_id: { eq: $org_id }, mood: { in: ["watch", "act"] } }, order_by: { created_at: desc }, limit: 1) {
    id
    org_id
    workflow_run_id
    kind
    scope
    topic
    mood
    title
    created_at
  }
}

subscription SourceChangeMatch {
  product(order_by: { id: desc }, limit: 1) {
    id
  }
}

subscription SourceChangeMatch {
  product(where: { quantity: { lt: 5 }, name: { like: "Mug \"x\" é" }, ok: true, gone: null, list: [1, 2.5] }, order_by: { updated_at: desc }, limit: 1) {
    id
    sku
    name
    updated_at
  }
}
